#!/usr/bin/env python3
"""
Round 144h (culprits), 3 October 2026. Needs round 144b.

Hell, a fourth basemap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 144h (3 October)\n\nNeeds round 144b. No tiles patch. No app.js?v= bump. Made in a separate chat\n("h" for Hell) while the "b" chat goes on with the layers; everything is in one\nnew block of app.js ("Hell, a fourth basemap" to "end of Hell") and one test\nblock before round 143b\'s, so it does not touch lines the other chat edits.\n\n- A fourth basemap, Hell (asked 3 October, after the owner\'s pictures: a red\n  sea round black land, a relief map cut by red rivers, hell\'s place names on\n  black, graveyards glowing on black; "nothing cheesy"). The same Earth from\n  the same open data in other colours: oxblood sea, darker in the deeps and\n  lighter on the shelves (AWS terrain heights, sea-dem); basalt-black land,\n  ash grey up the slopes (same tiles); cold blue-grey relief light over black\n  shadow (Mapterhorn, outline-dem); lakes dark blood, rivers thin red veins\n  with a faint glow, graveyards dull red from zoom 9, towns dark ash, roads\n  dark maroon, borders faint dark red (OpenFreeMap, boundaries); the label set\n  turned light on dark and grey (raster brightness min above max). No orange,\n  yellow or green; a test checks the colours.\n- Layers named outline-hell-* (HELL_IDS), added on first choice just above\n  plate-base, so the colour mapping and themes leave them alone\n  (GLAD_BASE_LAYERS and themeTouches already skip "outline-").\n- Reached by wrapping, not editing: basemapPanelHtml adds the "Hell" choice;\n  setBasemap adds and shows the layers and sets BASE_GRADE.hell = {} and\n  THEME_BY_BASEMAP.hell = "bright"; the hologram\'s holo-on mark hides them\n  unless the hologram keeps the basemap under it.\n- Not seen against real tiles (the sandbox cannot reach them): check the look\n  live.\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round144h: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 144b" not in h.read_text(encoding="utf-8"):
        sys.exit("round144h: round 144b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round144h: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round144h: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round144h: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
